  case (sensor_sel)
    2'b00: digital_temp <= adc_out;
    2'b01: digital_press <= adc_out;
    2'b10: digital_humid <= adc_out;
    default: begin
      digital_temp <= 0;
      digital_press <= 0;
      digital_humid <= 0;
    end
  endcase
end

endmodule

