  input [68:0] data_in,
  input wr_en,
  input rd_en,
  input rst,
  output empty,
  output full,
  output [68:0] data_out
);

  reg [68:0] memory [0:31];
  reg [4:0] head;
  reg [4:0] tail;
  wire [4:0] count;
