      if (wr_en && !full) begin
        memory[head] <= data_in;
        head <= head + 1;
        if (head == 32) begin
          head <= 0;
        end
      end
      if (rd_en && !empty) begin
        data_out <= memory[tail];
        tail <= tail + 1;
        if (tail == 32) begin
          tail <= 0;
        end
      end
      empty <= (count == 0);
      full <= (count == 32);
    end
  end

