    state <= CMD_IDLE;
    cmd_reg <= 0;
    data_in_reg <= 0;
    mode_reg <= 0;
    data_en_reg <= 0;
    cmd_ack_reg <= 0;
    data_ack_reg <= 0;
    data_out_reg <= 0;
end else begin
    case (state)
    CMD_IDLE: begin
    cmd_ack_reg <= 0;
    if (cmd != 0) begin
    cmd_reg <= cmd;
    state <= CMD_SEND;
end
end
    CMD_SEND: begin
    crc_data <= cmd_reg;
    crc_cmd <= cmd_reg;
    cmd_ack_reg <= 1;
    state <= CMD_ACK;
end
    CMD_ACK: begin
    if (crc_out == 8'h00) begin
    if (mode == 1) begin
    state <= DATA_SEND;
end else begin
    state <= CMD_IDLE;
end
