    data_ack_reg <= 0;
    if (data_en == 1) begin
    data_in_reg <= data_in;
    state <= DATA_SEND;
end
end
    DATA_SEND: begin
    crc_data <= data_in_reg;
    data_ack_reg <= 1;
    state <= DATA_ACK;
end
    DATA_ACK: begin
    if (crc_out == 8'h00) begin
    if (mode == 1) begin
    state <= DATA_RECEIVE;
end else begin
    state <= CMD_IDLE;
end
end
end
    DATA_RECEIVE: begin
    crc_in <= data_out_reg;
    data_ack_reg <= 1;
    state <= DATA_ACK;
end
endcase
end
end

