    if (rst) begin
    data_out_reg <= 0;
end else begin
    case (state)
    DATA_IDLE: begin
    data_out_reg <= 0;
end
    DATA_SEND: begin
    data_out_reg <= data_in_reg;
end
    DATA_RECEIVE: begin
    data_out_reg <= data_out;
end
endcase
end
