        if (hours < 10) begin
            hours_display = hours;
        end else if (hours < 20) begin
            hours_display = hours - 10;
        end else begin
            hours_display = hours - 20;
        end
    end else begin
        if (minutes < 10) begin
            minutes_display = minutes;
        end else begin
            minutes_display = minutes - 10;
        end
    end
end

