    crc_in_shifted <= {crc_in_shifted[crc_width-2:0], crc_check};
end
end

    // Shift register for shifted generated CRC
    always @(posedge clk) begin
    if (reset) begin
    crc_gen_shifted <= 0;
end else begin
    crc_gen_shifted <= {crc_gen_shifted[crc_width-2:0], crc_gen};
end
end

    // Calculation of CRC checksum
    always @(posedge clk) begin
    if (reset) begin
    crc_reg <= 0;
