    wire [15:0] PCPrime;
    assign PCPrime = Branch ? {PC[14:0], IR[7:0], 1'b0} : PC + 1;
    wire [15:0] PCJump;
    assign PCJump = {PC[15:12], IR[7:0], 1'b0};

