parameter HEIGHT = 480;
parameter BORDER_WIDTH = 10;
parameter OBJECT_SIZE = 30;
parameter OBJECT_COLOR = 3'b111;
parameter BORDER_COLOR = 3'b111;
parameter BACKGROUND_COLOR = 2'b011;

